import React, { useEffect, useState } from "react";
import { useParams } from "react-router-dom";
import { FiMapPin } from "react-icons/fi";
import TabBar from "../../components/common/TabBar";
import ServiceTile from "../../components/common/ServiceTile";
import errorImage from "../../images/errorLoading.png";

const BusinessPage: React.FC = () => {
  const params = useParams();
  const [salon, setSalon] = useState<any>(null);
  const [loading, setLoading] = useState(true);
  const [imgSrc, setImgSrc] = useState(errorImage);

  const [activeTab, setActiveTab] = useState("");
  const [showPopup, setShowPopup] = useState(false);
  const [selectedService, setSelectedService] = useState<any>(null);
  const [selectedDate, setSelectedDate] = useState("");

  /* ----------------------------------------------------------
      ALWAYS FETCH BUSINESS FROM DATABASE
  -----------------------------------------------------------*/
  useEffect(() => {
    const fetchBusiness = async () => {
      try {
        const res = await fetch(
          `http://localhost:5000/api/public/businesses/${params.id}`
        );
        const data = await res.json();

        setSalon(data);

        setImgSrc(
          data?.imageUrl
            ? `http://localhost:5000${data.imageUrl}`
            : errorImage
        );
      } catch (err) {
        console.error("Error fetching business:", err);
      } finally {
        setLoading(false);
      }
    };

    fetchBusiness();
  }, [params.id]);

  /* ----------------------------------------------------------
      CREATE CATEGORY LIST
  -----------------------------------------------------------*/
  const categories = salon?.services
    ? Array.from(
        new Set(
          salon.services.map((s: any) => s.category || "Services")
        )
      )
    : [];

  useEffect(() => {
    if (categories.length > 0) {
      setActiveTab(categories[0]);
    }
  }, [salon]);

  /* ----------------------------------------------------------
      LOADING / ERROR STATES
  -----------------------------------------------------------*/
  if (loading) {
    return (
      <div style={{ padding: 20 }}>
        <TabBar type="customer" />
        Loading salon…
      </div>
    );
  }

  if (!salon) {
    return (
      <div style={{ padding: 20 }}>
        <TabBar type="customer" />
        Salon not found.
      </div>
    );
  }

  /* ----------------------------------------------------------
      POPUP HANDLERS
  -----------------------------------------------------------*/
  const openPopup = (service: any) => {
    setSelectedService(service);
    setShowPopup(true);
  };

  const closePopup = () => {
    setShowPopup(false);
    setSelectedService(null);
    setSelectedDate("");
  };

  const handleConfirmBooking = () => {
    if (!selectedDate) {
      alert("Please choose a date and time!");
      return;
    }
    alert(
      `Appointment booked for "${selectedService.name}" on ${selectedDate}`
    );
    closePopup();
  };

  const displayedServices = salon.services?.filter(
    (s: any) =>
      (s.category || "Services") === activeTab
  );

  return (
    <div
      style={{
        backgroundColor: "#F1DEDE",
        minHeight: "100vh",
        paddingBottom: "40px",
      }}
    >
      <TabBar type="customer" />

      <div
        style={{
          width: "90%",
          maxWidth: "900px",
          margin: "40px auto 0 auto",
          backgroundColor: "#fff",
          borderRadius: "16px",
          boxShadow: "0 4px 10px rgba(0,0,0,0.12)",
          overflow: "hidden",
        }}
      >
        {/* Header Image */}
        <img
          src={imgSrc}
          onError={() => setImgSrc(errorImage)}
          alt={salon.businessName}
          style={{
            width: "100%",
            height: "220px",
            objectFit: "cover",
          }}
        />

        <div style={{ padding: "24px" }}>
          <h2 style={{ fontSize: "24px", fontWeight: 700 }}>
            {salon.businessName}
          </h2>

          {/* Location */}
          <div
            style={{
              display: "flex",
              alignItems: "center",
              marginTop: "6px",
              color: "#7A7A7A",
              fontSize: "14px",
            }}
          >
            <FiMapPin size={16} style={{ marginRight: "4px" }} />
            {salon.address}, {salon.city}
          </div>

          {/* Description */}
          <p
            style={{
              marginTop: "12px",
              color: "#555",
              fontSize: "14px",
            }}
          >
            {salon.description || "No description available."}
          </p>

          {/* Categories */}
          <div
            style={{
              display: "flex",
              gap: "20px",
              borderBottom: "1px solid #e5e5e5",
              marginTop: "20px",
            }}
          >
            {categories.map((cat, i) => (
              <button
                key={cat || i}
                onClick={() => setActiveTab(cat)}
                style={{
                  border: "none",
                  background: "none",
                  fontWeight: 500,
                  color: activeTab === cat ? "#000" : "#7A7A7A",
                  borderBottom:
                    activeTab === cat
                      ? "2px solid #000"
                      : "2px solid transparent",
                  padding: "10px 0",
                  cursor: "pointer",
                }}
              >
                {cat}
              </button>
            ))}
          </div>

          {/* Services */}
          <div style={{ marginTop: "20px" }}>
            {displayedServices?.map((service: any, index: number) => (
              <ServiceTile
                key={service._id || index}
                name={service.name}
                price={service.price}
                duration={service.duration}
                description={service.description}
                onClick={() => openPopup(service)}
              />
            ))}
          </div>
        </div>
      </div>

      {/* Popup */}
      {showPopup && (
        <div
          onClick={closePopup}
          style={{
            position: "fixed",
            top: 0,
            left: 0,
            width: "100%",
            height: "100%",
            background: "rgba(0,0,0,0.5)",
            display: "flex",
            justifyContent: "center",
            alignItems: "center",
            zIndex: 9999,
          }}
        >
          <div
            onClick={(e) => e.stopPropagation()}
            style={{
              background: "#fff",
              borderRadius: "12px",
              padding: "30px",
              width: "380px",
              boxShadow: "0 4px 10px rgba(0,0,0,0.3)",
            }}
          >
            <h3 style={{ marginBottom: "15px" }}>Book Appointment</h3>

            {selectedService && (
              <>
                <p>
                  <strong>Service:</strong> {selectedService.name}
                </p>
                <p>
                  <strong>Price:</strong> {selectedService.price} BD
                </p>
                <p>
                  <strong>Duration:</strong> {selectedService.duration}
                </p>
              </>
            )}

            <label style={{ display: "block", marginTop: "15px" }}>
              Choose Date & Time:
            </label>
            <input
              type="datetime-local"
              value={selectedDate}
              onChange={(e) => setSelectedDate(e.target.value)}
              style={{
                width: "100%",
                padding: "10px",
                marginTop: "5px",
                borderRadius: "8px",
                border: "1px solid #ccc",
              }}
            />

            <div
              style={{
                marginTop: "20px",
                display: "flex",
                justifyContent: "flex-end",
                gap: "10px",
              }}
            >
              <button
                onClick={closePopup}
                style={{
                  background: "transparent",
                  border: "1px solid #ccc",
                  borderRadius: "8px",
                  padding: "8px 16px",
                  cursor: "pointer",
                }}
              >
                Cancel
              </button>

              <button
                onClick={handleConfirmBooking}
                style={{
                  background: "#27374d",
                  color: "#fff",
                  border: "none",
                  borderRadius: "8px",
                  padding: "8px 16px",
                  cursor: "pointer",
                }}
              >
                Confirm
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default BusinessPage;
